#![allow(dead_code)]
use std::any::{Any, TypeId};
use std::cell::Cell;
use std::hint::black_box;
use std::num::{NonZeroU8, NonZeroU32};
use std::time::Instant;

trait Codec: Copy + PartialEq + 'static {
    const N: u32;
    fn encode(self) -> u32;
    fn decode(ordinal: u32) -> Option<Self>;
    fn discriminant(self) -> i64;
}

// Mirrors the two independent priorities of an EffectiveValue. The caller
// supplies the already validated/coerced value. Both builds use this body.
struct Slot<T: Copy> {
    value: Cell<T>,
    base: Cell<Option<T>>,
    priority: Cell<i8>,
    base_priority: Cell<i8>,
}
impl<T: Copy + PartialEq> Slot<T> {
    fn new(default: T) -> Self {
        Self { value: Cell::new(default), base: Cell::new(None), priority: Cell::new(9), base_priority: Cell::new(9) }
    }
    #[inline(never)]
    fn write(&self, value: T, priority: i8) -> (Option<T>, bool) {
        let mut old = None;
        let mut base_changed = false;
        if priority <= self.priority.get() {
            let previous = self.value.replace(value);
            self.priority.set(priority);
            if previous != value { old = Some(previous) }
        }
        if priority >= 0 && priority <= self.base_priority.get() {
            base_changed = self.base.replace(Some(value)) != Some(value);
            self.base_priority.set(priority);
        }
        (old, base_changed)
    }
    fn begin_reevaluation(&self, clear_local: bool) {
        if self.priority.get() != 0 || clear_local { self.priority.set(9) }
        if self.base_priority.get() != 0 || clear_local { self.base_priority.set(9) }
    }
}

// The identity, metadata callback and value at the public boundary remain the
// actual enum type in all three configurations.
struct Property<E: Codec> {
    #[cfg(native)] slot: Slot<E>,
    #[cfg(word)] slot: Slot<NonZeroU32>,
    #[cfg(byte)] slot: Slot<NonZeroU8>,
    #[cfg(cache)] current: Cell<E>,
    coerce: Option<fn(E) -> E>,
}
type Change<'a> = dyn FnMut(TypeId, &dyn Any, &dyn Any, bool) + 'a;

impl<E: Codec> Property<E> {
    fn new() -> Self {
        let default = E::decode(1).unwrap();
        Self { slot: Slot::new(Self::store(default)), #[cfg(cache)] current: Cell::new(default), coerce: Some(|e| {
            if e.encode() == E::N { E::decode(1).unwrap() } else { e }
        }) }
    }
    #[cfg(native)] #[inline] fn store(value: E) -> E { value }
    #[cfg(native)] #[inline] fn load(value: E) -> E { value }
    #[cfg(word)] #[inline] fn store(value: E) -> NonZeroU32 { NonZeroU32::new(value.encode()).unwrap() }
    #[cfg(word)] #[inline] fn load(value: NonZeroU32) -> E { E::decode(value.get()).unwrap() }
    #[cfg(byte)] #[inline] fn store(value: E) -> NonZeroU8 { NonZeroU8::new(u8::try_from(value.encode()).unwrap()).unwrap() }
    #[cfg(byte)] #[inline] fn load(value: NonZeroU8) -> E { E::decode(value.get() as u32).unwrap() }

    fn set(&self, value: E, priority: i8, coerce: bool, change: &mut Change<'_>) {
        let new = if coerce { self.coerce.map_or(value, |f| f(value)) } else { value };
        let (old, base_changed) = self.slot.write(Self::store(new), priority);
        if let Some(old) = old {
            #[cfg(cache)] let old = {let _ = old; self.current.replace(new)};
            #[cfg(not(cache))] let old = Self::load(old);
            change(TypeId::of::<E>(), &old, &new, true);
        } else if base_changed {
            change(TypeId::of::<E>(), &new, &new, false);
        }
    }
}
trait Lane {
    fn verify_codec(&self) -> u64;
    fn step(&self, random: u32, change: &mut Change<'_>) -> u32;
    fn read(&self) -> u32;
    fn storage_bytes(&self) -> usize;
}

impl<E: Codec> Lane for Property<E> {
    fn verify_codec(&self) -> u64 {
        assert!(E::decode(0).is_none() && E::decode(E::N + 1).is_none());
        let mut checksum = 0u64;
        for ordinal in 1..=E::N {
            let value = E::decode(ordinal).unwrap();
            let roundtrip = Self::load(Self::store(value));
            assert!(roundtrip == value && value.encode() == ordinal);
            checksum = checksum.wrapping_mul(131).wrapping_add(value.discriminant() as u64);
        }
        checksum
    }
    fn read(&self) -> u32 {
        #[cfg(cache)] {self.current.get().encode()}
        #[cfg(not(cache))] {Self::load(self.slot.value.get()).encode()}
    }
    fn step(&self, random: u32, change: &mut Change<'_>) -> u32 {
        if random & 7 == 0 { self.slot.begin_reevaluation(random & 0x40 == 0); }
        let value = E::decode(1 + ((random >> 8) % E::N)).unwrap();
        let priority = ((random >> 23) % 5) as i8 - 1;
        self.set(value, priority, random & 4 != 0, change);
        self.read()
    }
    fn storage_bytes(&self) -> usize {
        #[cfg(cache)] {std::mem::size_of::<(Slot<NonZeroU8>, E)>()}
        #[cfg(not(cache))] {std::mem::size_of_val(&self.slot)}
    }
}

include!("enums.rs");

#[repr(C)] struct Timespec { sec:i64, ns: i64 }
unsafe extern "C" { fn clock_gettime(clock:i32, time:*mut Timespec) -> i32; }
fn cpu() -> i64 {
    let mut t=Timespec{sec:0,ns:0};assert_eq!(unsafe{clock_gettime(3,&mut t)},0);t.sec*1_000_000_000+t.ns
}

fn main() {
    let lanes=registered();
    let hash=lanes.iter().fold(0u64, |s, p| s.wrapping_mul(31).wrapping_add(p.verify_codec()));
    let state_bytes:usize=lanes.iter().map(|p|p.storage_bytes()).sum();
    let mode=std::env::args().nth(1).unwrap(); let mut seed=93138971u32;let mut sum=0u64;let mut notifications=0u64;
    let mut change=|id, old:&dyn Any, value:&dyn Any, effective| {
        assert_eq!(old.type_id(),id);assert_eq!(value.type_id(),id);
        notifications+=if effective{2}else{1};
    };
    let wall=Instant::now();let start=cpu();
    for _ in 0..2_000_000usize {
        seed = seed.wrapping_mul(1664525).wrapping_add(1013904223);let prop=&lanes[(seed as usize>>16)%lanes.len()];
        let value=if mode=="read"{prop.read()}else{prop.step(seed, &mut change)};
        sum+=black_box(value) as u64;
    }
    let elapsed=cpu()-start;
    println!("{} {} {} {} {} {} {} {}",mode,lanes.len(),hash,state_bytes,sum,notifications,elapsed,wall.elapsed().as_nanos());
}

