import gzip,json,re,struct,subprocess,sys
from pathlib import Path
elf=Path(sys.argv[1]);symbols=Path(sys.argv[2]);sections={}
for line in subprocess.check_output(['readelf','-SW',elf],text=True).splitlines():
 m=re.match(r'^\s*\[\s*\d+\]\s+(\S+)\s+\S+\s+([\da-f]+)\s+([\da-f]+)\s+([\da-f]+)',line)
 if m:sections[m[1]]=tuple(int(x,16) for x in m.groups()[1:])
raw=elf.read_bytes();va,off,_=sections['.text'];rv,ro,rs=sections['.rodata']
leaves={};names={}
with gzip.open(symbols,'rt') as nm:
 for line in nm:
  row=line.strip().split(' ',3)
  if len(row)!=4 or row[2] not in ['t','T'] or not row[3].endswith('>::any_value_type_name'):continue
  pc,n=int(row[0],16),int(row[1],16);code=raw[off+pc-va:off+pc-va+n]
  assert code[:3]==b'\x48\x8d\x05' and code[-1]==0xc3
  addr=pc+7+struct.unpack_from('<i',code,3)[0]
  if n==11 and code[7]==0x6a and code[8]<128 and code[9]==0x5a:
   length=code[8]
  else:
   assert n==13 and code[7]==0xba
   length=struct.unpack_from('<I',code,8)[0]
  assert rv<=addr<addr+length<=rv+rs
  names[addr,addr+length]=raw[ro+addr-rv:ro+addr-rv+length].decode()
  leaves[pc]=n
covered=0;high=0
for start,end in sorted(names):
 covered+=max(0,end-max(start,high));high=max(high,end)
fde=0;count=0;proc=subprocess.Popen(['readelf','-wf',elf],stdout=subprocess.PIPE,text=True)
for line in proc.stdout:
 m=re.match(r'^\s*[0-9a-fA-F]+\s+([0-9a-fA-F]+)\s+\S+\s+FDE cie=\S+ pc=([0-9a-fA-F]+)\.\.([0-9a-fA-F]+)',line)
 if m:
  pc=int(m[2],16)
  if pc in leaves:
   assert int(m[3],16)-pc==leaves[pc];fde+=4+int(m[1],16);count+=1
assert proc.wait()==0
print(json.dumps({'distinct_leaf_addresses':len(leaves),'text_bytes':sum(leaves.values()),'distinct_utf8_names':len(set(names.values())),'union_rodata_bytes':covered,'fde_count':count,'fde_bytes':fde,'index_bytes':8*count}))
